<?php require_once __DIR__.'/auth.php'; require_admin(); $pdo=db(); $keys=['name','shortName','phone','email','address','founded']; if($_SERVER['REQUEST_METHOD']==='POST'){foreach($keys as $k){$st=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$st->execute([$k,trim($_POST[$k]??'')]);}$message='Settings saved.';} $settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM site_settings') as $r)$settings[$r['setting_key']]=$r['setting_value'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website Settings</title><style>body{font-family:Arial;background:#f5f1ea;padding:30px}.box{max-width:700px;margin:auto;background:#fff;padding:25px;border-radius:8px}label{display:block;margin-top:14px;font-weight:bold}input{width:100%;padding:11px;box-sizing:border-box;margin-top:5px}button{margin-top:20px;background:#7d402d;color:#fff;padding:11px 18px;border:0;border-radius:5px}</style></head><body><div class="box"><a href="index.php">← Dashboard</a><h1>Website Settings</h1><?php if(!empty($message))echo '<p style="color:green">'.$message.'</p>';?><form method="post"><?php foreach($keys as $k):?><label><?php echo htmlspecialchars($k);?><input name="<?php echo $k;?>" value="<?php echo htmlspecialchars($settings[$k]??'');?>"></label><?php endforeach;?><button>Save Settings</button></form></div></body></html>
